/** Exact-only lookup. It never substitutes a family/default asset. */
export function resolveWorldAsset(
  ref: string,
  onDiagnostic?: (diagnostic: WorldAssetResolutionDiagnostic) => void
): GeneratedWorldAsset | undefined {
  const asset = GENERATED_WORLD_ASSETS[ref];
  if (!asset) onDiagnostic?.({ ref, reason: 'unsupported-exact-ref' });
  return asset;
}
